struct strabismus;
class pyrAspectRatio;

extern struct strabismus g_strabismusValue;
extern pyrAspectRatio g_pyrAR;

struct strabismus{          // 斜视数据
    double leftEyeLR;       // 左眼水平斜视
    double leftEyeUD;       // 左眼垂直斜视
    double rightEyeLR;
    double rightEyeUD;

    void clear(){
        leftEyeLR = 0;
        leftEyeUD = 0;
        rightEyeLR = 0;
        rightEyeUD = 0;
    }
};

// 6 张图像的瞳孔高宽比，并提供计算均值的函数（用于判断上睑下垂）
class pyrAspectRatio{
public:
    double R_AspectRatio[22];
    double L_AspectRatio[22];

    // 重置
    void clear(){
        memset(&R_AspectRatio, 0, 22 * sizeof (double));
        memset(&L_AspectRatio, 0, 22 * sizeof (double));
    }

    // 得到左眼 1~6 图平均瞳孔高宽比
    double getLeftAveraVal()
    {
        double avaraVal = 0;
        double sum = 0;
        double tmpMax = 0;
        double tmpMin = 1;
        for(int i=0;i<6;i++){
            sum += L_AspectRatio[i];
            if(L_AspectRatio[i] > tmpMax){
                tmpMax = L_AspectRatio[i];
            }
            if(L_AspectRatio[i] < tmpMin){
                tmpMin = L_AspectRatio[i];
            }
//            qDebug()<<"L_a["<<i<<"]="<<L_AspectRatio[i];
        }
//        qDebug()<<"Left--tmpMax="<<tmpMax<<",tmpMin="<<tmpMin<<"sum="<<sum;
        avaraVal = (sum - tmpMax - tmpMin)/4;
        return avaraVal;
    }

    // 得到右眼 1~6 图平均瞳孔高宽比
    double getRightAveraVal()
    {
        double avaraVal = 0;
        double sum = 0;
        double tmpMax = 0;
        double tmpMin = 1;
        for(int i=0;i<6;i++){
            sum += R_AspectRatio[i];
            if(R_AspectRatio[i] > tmpMax){
                tmpMax = R_AspectRatio[i];
            }
            if(R_AspectRatio[i] < tmpMin){
                tmpMin = R_AspectRatio[i];
            }
//            qDebug()<<"R_a["<<i<<"]="<<R_AspectRatio[i];
        }
//        qDebug()<<"Right--tmpMax="<<tmpMax<<",tmpMin="<<tmpMin<<"su,="<<sum;
        avaraVal = (sum - tmpMax - tmpMin)/4;
        return avaraVal;
    }

    // 是否眨眼了
    bool checkIsBlinked()
    {
        /* 判断逻辑：所有图像的上睑下垂状态一致，即都为是或都为否，则为非眨眼 */
        bool is_ptosis_new;
        bool is_ptosis_old = (R_AspectRatio[0] < 0.75);
        for (int i = 1; i < 22; i++) {
            is_ptosis_new = (R_AspectRatio[i] < 0.75);
            if (is_ptosis_new != is_ptosis_old) {
                return true;
            }
        }
        is_ptosis_old = (L_AspectRatio[0] < 0.75);
        for (int i = 1; i < 22; i++) {
            is_ptosis_new = (L_AspectRatio[i] < 0.75);
            if (is_ptosis_new != is_ptosis_old) {
                return true;
            }
        }
        return false;
    }
};

